#!/usr/bin/env python3
"""V7.3 Daily self-healing patch component."""

def _replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label} expected one match, found {count}")
    return text.replace(old, new, 1)

def apply_daily_anchor_patch(text):
    old = '''    def _daily_anchor_check(self, anchor, ref):\n        """Vision-first route verification with no OCR in the hot path."""\n        name = str(anchor or "").upper()\n        screen, conf, detail = self._vision_identify_screen(ref)\n        accepted = {\n            "HOME": {"HOME"},\n            "MAIL": {"MAIL"},\n            "SHOP": {"SHOP", "QUEST"},\n            "QUEST": {"QUEST"},\n            "EVENT": {"EVENT"},\n            "RECRUIT": {"RECRUIT"},\n            "REGULAR_RECRUIT": {"RECRUIT"},\n            "CHAIN": {"CHAIN"},\n            "IDLE_POPUP": {"IDLE_POPUP"},\n        }\n        if name in accepted:\n            ok = screen in accepted[name]\n            # V7.2.1: HOME is the only screen allowed a bounded soft match.\n            # Live Home art/animation can shift its pHash farther than the\n            # recorded reference even though HOME remains the nearest screen.\n            if not ok and name == "HOME" and screen == "UNKNOWN":\n                match = re.search(r"nearest\\s+HOME\\s+d=([0-9.]+)", str(detail or ""))\n                if match:\n                    try:\n                        home_distance = float(match.group(1))\n                    except Exception:\n                        home_distance = 999.0\n                    if home_distance <= 20.0:\n                        return True, (\n                            f"vision=HOME~ {conf:.0f}% • soft {detail} "\n                            f"(limit=20.0)"\n                        )\n            return ok, f"vision={screen} {conf:.0f}% • {detail}"\n        return True, "no anchor configured"\n'''
    new = '''    def _daily_header_ocr_tokens(self, ref):\n        """Bounded title/header OCR used only when visual identity is UNKNOWN."""\n        if not HAS_TESSERACT:\n            return ""\n        pieces = []\n        for roi in ((0, 0, 760, 190), (0, 0, 1536, 115)):\n            text = self._daily_ocr_region(ref, roi, psm=11)\n            if text:\n                pieces.append(text)\n        return normalize_daily_word(" ".join(pieces))\n\n    @staticmethod\n    def _daily_screen_token_rules(text):\n        text = normalize_daily_word(text)\n        words = set(text.split())\n        # Strong, page-specific evidence only. HOME and IDLE remain image-only.\n        if "CHAIN" in words and "CAMPAIGN" in words:\n            return "CHAIN"\n        if "RECRUIT" in words:\n            return "RECRUIT"\n        if "MAIL" in words:\n            return "MAIL"\n        if "QUEST" in words and "SHOP" not in words:\n            return "QUEST"\n        if "SHOP" in words:\n            return "SHOP"\n        if "EVENT" in words and "SHOP" not in words:\n            return "EVENT"\n        return None\n\n    def _daily_ocr_recognize_screen(self, ref):\n        text = self._daily_header_ocr_tokens(ref)\n        screen = self._daily_screen_token_rules(text)\n        return screen, text\n\n    def _daily_anchor_check(self, anchor, ref):\n        """Fast visual verification with conservative OCR self-healing fallback."""\n        name = str(anchor or "").upper()\n        screen, conf, detail = self._vision_identify_screen(ref)\n        accepted = {\n            "HOME": {"HOME"},\n            "MAIL": {"MAIL"},\n            "SHOP": {"SHOP", "QUEST"},\n            "QUEST": {"QUEST"},\n            "EVENT": {"EVENT"},\n            "RECRUIT": {"RECRUIT"},\n            "REGULAR_RECRUIT": {"RECRUIT"},\n            "CHAIN": {"CHAIN"},\n            "IDLE_POPUP": {"IDLE_POPUP"},\n        }\n        if name in accepted:\n            ok = screen in accepted[name]\n            if ok:\n                return True, f"vision={screen} {conf:.0f}% • {detail}"\n            # HOME keeps the bounded pHash recovery from 7.2.1.\n            if name == "HOME" and screen == "UNKNOWN":\n                match = re.search(r"nearest\\s+HOME\\s+d=([0-9.]+)", str(detail or ""))\n                if match:\n                    try:\n                        home_distance = float(match.group(1))\n                    except Exception:\n                        home_distance = 999.0\n                    if home_distance <= 20.0:\n                        return True, (\n                            f"vision=HOME~ {conf:.0f}% • soft {detail} "\n                            f"(limit=20.0)"\n                        )\n            # Only an UNKNOWN visual result may be overridden. Never override a\n            # confidently recognized different page, and never OCR-override HOME/IDLE.\n            if screen == "UNKNOWN" and name in {"MAIL", "SHOP", "QUEST", "EVENT", "RECRUIT", "REGULAR_RECRUIT", "CHAIN"}:\n                ocr_screen, ocr_text = self._daily_ocr_recognize_screen(ref)\n                if ocr_screen in accepted[name]:\n                    self._vision_learn_screen(ocr_screen, ref, evidence=f"OCR:{name}")\n                    return True, f"ocr={ocr_screen} • learned live fingerprint • {ocr_text[:90]}"\n                if ocr_text:\n                    return False, f"vision={screen} {conf:.0f}% • {detail} • OCR={ocr_text[:90]}"\n            return False, f"vision={screen} {conf:.0f}% • {detail}"\n        return True, "no anchor configured"\n'''
    text = _replace_once(text, old, new, "Daily OCR self-healing anchors")
    return text
